/**
 * Объявления типов глобального объекта `Server`, доступного в серверных
 * XScript-шаблонах WebSoft HCM (блоки `<% ... %>` в файлах `.html` / `.bs`).
 */
interface ServerObject {
  /**
   * Серверное подключение: выполняет другой файл шаблона и вставляет результат
   * его выполнения в текущую позицию. Подключаемый файл использует общую
   * с вызывающим кодом область видимости переменных и функций, поэтому может
   * читать и определять переменные, доступные вызывающему коду после выполнения.
   *
   * Возвращаемое значение не используется ни в одном месте вызова в пакете
   * (подключаемые файлы не возвращают значений, используемых вызывающим кодом).
   * @param {string} path - Путь к выполняемому шаблону. Может быть относительным к текущему
   * шаблону (например, `"include/user_init.html"`,
   * `"../include/access_init.html"`) или абсолютным, обычно сформированным
   * с помощью `AppDirectoryPath()` (например, `AppDirectoryPath() + "/wt/web/view_access_panel.html"`).
   * Также может быть вычисляемым строковым выражением.
   * @example
   * Server.Execute("include/user_init.html");
   * Server.Execute(AppDirectoryPath() + "/wt/web/view_access_panel.html");
   */
  Execute(path: string): void;
}

/**
 * Глобальный объект серверного шаблона.
 *
 * Доступен только в серверном коде XScript-шаблонов; отсутствует
 * в клиентском JavaScript, отправляемом в браузер.
 */
declare const Server: ServerObject;
